-- Audit trail of every scoring rule that fired for a colonoscopy request.

CREATE TABLE colonoscopy_test_request_grade_rule (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at TIMESTAMPTZ DEFAULT NULL,

    colonoscopy_test_request_grade_id UUID NOT NULL
        REFERENCES colonoscopy_test_request_grade(id) ON DELETE CASCADE,
    rule_id VARCHAR(40) NOT NULL,
    axis VARCHAR(20) NOT NULL DEFAULT ''
        CHECK (axis IN ('appropriateness', 'urgency', 'completeness', 'risk', '')),
    category VARCHAR(50) NOT NULL DEFAULT '',
